  display: flex;
  align-items: center;
  gap: .625rem;
}
.logo {
  font-size: 1.25rem;
}
.site-name {
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: .02em;
  color: var(--color-text-primary);
}

