#main {
  padding: 3rem 1.5rem 4rem;
}
.page-content {
  max-width: 540px;
  margin: 0 auto;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text-primary);
}
.page-subtitle {
  margin-top: .375rem;
  color: var(--color-text-secondary);
  font-size: .9375rem;
}

/* ── Form card ── */
.form-card {
  margin-top: 2rem;
  background: var(--color-surface);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card);
  padding: 2rem;
}
.form-card h2 {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--color-border);
}

/* ── Form field wrapper ── */
.form-field {
  margin-bottom: 1.5rem;
}

/* ── Fieldset / legend ── */
fieldset {
  border: none;
  padding: 0;
}
legend {
  font-size: .9375rem;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: .375rem;
  width: 100%;
}
.required-marker {
  color: var(--color-error);
  margin-left: .125rem;
}

