.radio-label:has(input[type="radio"]:focus-visible) {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

.radio-text {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-text-primary);
}

/* ── Submit button ── */
.form-actions {
  margin-top: 1.75rem;
