    color: ButtonFace;
    border: 2px solid ButtonText;
  }
  .btn-primary:hover {
    background: Highlight;
    border-color: Highlight;
    color: HighlightText;
  }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0s !important;
