const form = document.getElementById('preferences-form');
const errorMsg = document.getElementById('notif-error');
const successMsg = document.getElementById('success-message');
const fieldset = form.querySelector('fieldset');

form.addEventListener('submit', (event) => {
  event.preventDefault();

  const selected = form.querySelector('input[name="notification-preference"]:checked');

  if (!selected) {
    // Show inline error and associate it with the fieldset
    fieldset.setAttribute('aria-describedby', 'notif-required-note notif-error');
    errorMsg.hidden = false;
    // Move focus to the first radio so the user can immediately correct
    form.querySelector('input[name="notification-preference"]').focus();
    successMsg.hidden = true;
    return;
  }

  // Valid — clear error, show success
  errorMsg.hidden = true;
  fieldset.setAttribute('aria-describedby', 'notif-required-note');
  successMsg.hidden = false;
});

// Clear error as soon as the user makes a selection
form.querySelectorAll('input[name="notification-preference"]').forEach((radio) => {
  radio.addEventListener('change', () => {
    errorMsg.hidden = true;
    fieldset.setAttribute('aria-describedby', 'notif-required-note');
  });
});

