    bp:   bp.map(v   => ({ id: v.id,                   help: v.help, targets: v.nodes.map(n => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
EOF", 'description': 'Run axe on rendered page', 'initial_wait': 30}, intention_summary='Run axe on rendered page', mcp_server_name=None, tool_title=None, type=<AssistantMessageToolRequestType.FUNCTION: 'function'>)

